  {id:391,type:'closing',style:'ready',block:'CIERRE',title:'FELICIDADES',subtitle:'Lo has conseguido',icon:'celebration',desc:'La Mirada Creativa completada. 365 días, 365 fotos con intención.\n\n🎉 Esto es solo el comienzo.'},
  {id:392,type:'closing',style:'ready',block:'CIERRE',title:'QUÉ HAS APRENDIDO',subtitle:'Tu nuevo vocabulario',icon:'school',desc:'Tienes vocabulario técnico, sensibilidad emocional, herramientas conceptuales y tu voz propia.\n\n🎓 Todo lo que necesitas para seguir disparando.'},
  {id:393,type:'closing',style:'ready',block:'CIERRE',title:'QUÉ SIGUE',subtitle:'El camino continúa',icon:'route',desc:'Esto no termina aquí. Repite el programa, crea tus ejercicios o sigue saliendo con tu cámara.\n\n🛤️ El camino es infinito.'},
  {id:394,type:'closing',style:'cover',block:'FINAL',title:'GRACIAS',subtitle:'Por entrenar tu mirada',icon:'favorite',desc:'Gracias por confiar en este sistema. Espero que te haya ayudado a ver el mundo con ojos nuevos. — Rafa\n\n❤️ Sigue mirando. Sigue disparando.'}
